// Languages with complete string coverage (menu + all in-game text). Only these are
// offered in the language selector: a language with only its ~15 menu strings
// would show a mostly-English game and make the toggle feel broken (it appeared to
// do nothing / only flip to German). Add a code here once that language's
// translations are finished. LANGUAGE_OPTIONS is kept full so
// getLanguageName can still resolve labels for legacy settings.
// zh, ja, ko and pt are offered with event prose still in English: the stories are being written.
const SUPPORTED_LANGUAGES = ['en', 'es', 'fr', 'ru', 'de', 'zh', 'ja', 'ko', 'pt'];
// Languages that put no space between words.
const UNSPACED_LANGUAGES = ['zh', 'ja'];

// Rarity words that agree with the item they describe.
//
// Spanish, French and Portuguese put the rarity after the item (Espada rara,
// Épée rare, Machado Raro); Spanish and French write it lowercase there,
// matching their sentence-case item names. German and Russian keep it first
// but inflect it (Seltenes Schwert, Редкая латная броня), and Russian then
// lowercases the noun it now leads. `weapons`/`armor` give each item type's
// gender; the masculine form is RARITY_TRANSLATIONS. Generic armor words
// (armadura, armure, Rüstung, броня) are feminine in all five.
// Languages missing here keep the rarity first and unchanged.
const GENDERED_RARITY = {
    es: {
        after: true, lowercase: true,
        weapons: { dagger: 'f', sword: 'f', axe: 'f', mace: 'f', chain: 'f', spear: 'f' },
        armor: 'f',
        f: { common: 'Común', uncommon: 'Poco común', rare: 'Rara', epic: 'Épica', legendary: 'Legendaria', cursed: 'Maldita' },
    },
    fr: {
        after: true, lowercase: true,
        weapons: { dagger: 'f', sword: 'f', axe: 'f', mace: 'f', chain: 'f', spear: 'f' },
        armor: 'f',
        f: { common: 'Commune', uncommon: 'Inhabituelle', rare: 'Rare', epic: 'Épique', legendary: 'Légendaire', cursed: 'Maudite' },
    },
    pt: {
        after: true,
        weapons: { dagger: 'f', sword: 'f', mace: 'f', chain: 'f', spear: 'f', gauntlet: 'f' },
        armor: 'f',
        f: { common: 'Comum', uncommon: 'Incomum', rare: 'Rara', epic: 'Épica', legendary: 'Lendária', cursed: 'Amaldiçoada' },
    },
    de: {
        weapons: { sword: 'n', axe: 'f', chain: 'f' },
        armor: { leather: 'f', chain: 'n', plate: 'f', bone: 'f', padded: 'm' },
        m: { common: 'Gewöhnlicher', uncommon: 'Ungewöhnlicher', rare: 'Seltener', epic: 'Epischer', legendary: 'Legendärer', cursed: 'Verfluchter' },
        f: { common: 'Gewöhnliche', uncommon: 'Ungewöhnliche', rare: 'Seltene', epic: 'Epische', legendary: 'Legendäre', cursed: 'Verfluchte' },
        n: { common: 'Gewöhnliches', uncommon: 'Ungewöhnliches', rare: 'Seltenes', epic: 'Episches', legendary: 'Legendäres', cursed: 'Verfluchtes' },
    },
    ru: {
        lowerNoun: true,
        weapons: { mace: 'f', chain: 'f', spear: 'n', gauntlet: 'f' },
        armor: 'f',
        f: { common: 'Обычная', uncommon: 'Необычная', rare: 'Редкая', epic: 'Эпическая', legendary: 'Легендарная', cursed: 'Проклятая' },
        n: { common: 'Обычное', uncommon: 'Необычное', rare: 'Редкое', epic: 'Эпическое', legendary: 'Легендарное', cursed: 'Проклятое' },
    },
};

function genderOf(language, type, key) {
    const rule = GENDERED_RARITY[language];
    if (!rule) return 'm';
    const table = type === 'armor' ? rule.armor : rule.weapons;
    return (typeof table === 'string' ? table : table?.[key]) || 'm';
}

function rarityForNoun(sceneOrGame, language, rarity, gender = 'm') {
    const rule = GENDERED_RARITY[language];
    const key = String(rarity || '').toLowerCase();
    const word = rule?.[gender]?.[key] || rule?.m?.[key] || translateRarity(sceneOrGame, rarity);
    return rule?.lowercase ? word.toLowerCase() : word;
}

function joinRarity(language, rarity, noun, joiner) {
    const rule = GENDERED_RARITY[language];
    if (!rarity) return noun;
    if (rule?.after) return [noun, rarity].join(joiner);
    const lead = rule?.lowerNoun && noun ? noun.charAt(0).toLowerCase() + noun.slice(1) : noun;
    return [rarity, lead].filter(Boolean).join(joiner);
}

/**
 * A rarity in front of (or after) a noun, agreeing with it: "Seltener Nahkampf",
 * "Редкий ближний бой". `gender` is 'm', 'f' or 'n' in the current language.
 * Where the rarity follows the noun, a category word such as "Cuerpo a
 * cuerpo" is not a noun it can agree with, so it goes in brackets instead:
 * "Cuerpo a cuerpo (raro)".
 */
export function rarityPhrase(sceneOrGame, rarity, noun, gender = 'm') {
    const language = getGameLanguage(sceneOrGame);
    const word = rarityForNoun(sceneOrGame, language, rarity, gender);
    if (!word) return noun;
    if (GENDERED_RARITY[language]?.after) return `${noun} (${word})`;
    const joiner = UNSPACED_LANGUAGES.includes(language) ? '' : ' ';
    return joinRarity(language, word, noun, joiner);
}

/** The rarity word alone, agreeing with a noun of `gender` ('m', 'f', 'n'). */
export function translateRarityFor(sceneOrGame, rarity, gender = 'm') {
    return rarityForNoun(sceneOrGame, getGameLanguage(sceneOrGame), rarity, gender);
}

export function getLanguageOptions() {
    return LANGUAGE_OPTIONS.filter(option => SUPPORTED_LANGUAGES.includes(option.code));
}

export function normalizeLanguageCode(language) {
    const value = String(language || 'en');
    const lower = value.toLowerCase();
    const legacy = {
        english: 'en',
        spanish: 'es',
        'español': 'es',
        french: 'fr',
        'français': 'fr',
        german: 'de',
        deutsch: 'de',
        japanese: 'ja',
        '日本語': 'ja',
        chinese: 'zh',
        '中文': 'zh',
        russian: 'ru',
        'русский': 'ru',
        korean: 'ko',
        '한국어': 'ko',
        portuguese: 'pt',
        'português': 'pt',
        'pt-br': 'pt',
    };
    return LANGUAGE_OPTIONS.some(option => option.code === lower)
        ? lower
        : legacy[lower] || 'en';
}

